return $input.all().map(i => {
  const j = i.json;
  const prompt = `You triage replies to B2B outreach for a sales rep.

Account: ${j.account}
Channel: ${j.event_type === 'email_reply' ? 'email' : 'LinkedIn'}
Our original outreach (may be empty): ${(j.original_outreach || '(unknown)').slice(0, 600)}
Their reply: ${(j.reply_snippet || '').slice(0, 600)}

HARD RULES for the suggested response:
- NEVER invent facts, pricing, numbers, product capabilities, or commitments. You do not know our pricing or specs.
- If they ask for specifics you don't have, acknowledge the question and say you'll follow up with exact details, or propose a short call.
- Match their tone; be brief and human; no placeholders like [name].

Respond with ONLY a JSON object:
{"classification": one of "interested" | "objection" | "not_now" | "unsubscribe" | "other",
 "suggested_response": a short (under 100 words), plain-text reply the rep could send as-is. Empty string if classification is unsubscribe.,
 "rationale": one sentence on why you classified it this way}`;
  return { json: { ...j, prompt } };
});

const esc = (s) => String(s == null ? '' : s).replace(/'/g, "''");
const rows = $('Build Prompt').all().map(i => i.json);
const outs = $input.all();
const ALLOWED = ['interested','objection','not_now','unsubscribe','other'];
return outs.map((o, idx) => {
  const src = rows[idx] || {};
  let cls = 'unclassified', resp = '', why = '';
  try {
    const raw = o.json.output ?? o.json.text ?? o.json.response ?? '';
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (parsed && ALLOWED.includes(parsed.classification)) cls = parsed.classification;
    resp = String(parsed && parsed.suggested_response || '').slice(0, 1500);
    why = String(parsed && parsed.rationale || '').slice(0, 300);
  } catch (e) { /* leave unclassified */ }
  return { json: {
    event_id: src.id, account: src.account, contact: src.contact || '',
    event_type: src.event_type, rep_email: src.rep_email || '',
    reply_snippet: src.reply_snippet || '',
    classification: cls, suggested_response: resp, rationale: why,
    classification_esc: esc(cls)
  } };
});

parameters.query:
UPDATE engagement_events
SET metadata = metadata || jsonb_build_object('triaged', true, 'classification', '{{ $json.classification_esc }}', 'triaged_at', now()::text)
WHERE id = {{ $json.event_id }}
RETURNING id;

